const https = require('https');
const http = require('http');
const { URL } = require('url');

// Test 1: http://localhost:47301/checkConnectivity?variant=3
function testLocalhost() {
    console.log('=== Test 1: http://localhost:47301/checkConnectivity?variant=3 ===');

    return new Promise((resolve, reject) => {
        const req = http.request({
            hostname: 'localhost',
            port: 47301,
            path: '/checkConnectivity?variant=3',
            method: 'GET',
            timeout: 5000
        }, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                console.log(`Status: ${res.statusCode} ${res.statusMessage}`);
                console.log('Headers:', JSON.stringify(res.headers, null, 2));
                console.log('Response body:');
                console.log(data);
                console.log('--- End of Test 1 ---\n');
                resolve();
            });
        });

        req.on('error', (err) => {
            console.error(`Error connecting to localhost:47301: ${err.message}`);
            console.log('--- End of Test 1 ---\n');
            resolve(); // Resolve anyway to continue with next test
        });

        req.on('timeout', () => {
            console.error('Timeout connecting to localhost:47301');
            req.destroy();
            console.log('--- End of Test 1 ---\n');
            resolve(); // Resolve anyway to continue with next test
        });

        req.end();
    });
}

// Test 2: https://httpstat.us/200
function testHttpStat() {
    console.log('=== Test 2: https://httpstat.us/200 ===');

    return new Promise((resolve, reject) => {
        const url = new URL('https://httpstat.us/200');

        const req = https.request({
            hostname: url.hostname,
            port: url.port || 443,
            path: url.pathname + url.search,
            method: 'GET',
            timeout: 5000
        }, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                console.log(`Status: ${res.statusCode} ${res.statusMessage}`);
                console.log('Headers:', JSON.stringify(res.headers, null, 2));
                console.log('Response body:');
                console.log(data);
                console.log('--- End of Test 2 ---\n');
                resolve();
            });
        });

        req.on('error', (err) => {
            console.error(`Error connecting to https://httpstat.us/200: ${err.message}`);
            console.log('--- End of Test 2 ---\n');
            resolve();
        });

        req.on('timeout', () => {
            console.error('Timeout connecting to https://httpstat.us/200');
            req.destroy();
            console.log('--- End of Test 2 ---\n');
            resolve();
        });

        req.end();
    });
}

// Run tests
async function runTests() {
    console.log('Starting connectivity tests...\n');

    try {
        await testLocalhost();
        await testHttpStat();

        console.log('All tests completed.');
    } catch (error) {
        console.error('Unexpected error:', error);
    }
}

runTests();

const https = require('https');
const http = require('http');
const { URL } = require('url');
const fs = require('fs');

// Read .env.test file
function readEnvTestFile() {
    try {
        return fs.readFileSync('.env.test', 'utf8');
    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        return '';
    }
}

// Test 1: http://localhost:47301/checkConnectivity?variant=3
function testLocalhost() {
    console.log('=== Test 1: http://localhost:47301/checkConnectivity?variant=3 ===');

    return new Promise((resolve, reject) => {
        const req = http.request({
            hostname: 'localhost',
            port: 47301,
            path: '/checkConnectivity?variant=3',
            method: 'GET',
            timeout: 5000
        }, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                console.log(`Status: ${res.statusCode} ${res.statusMessage}`);
                console.log('Headers:', JSON.stringify(res.headers, null, 2));
                console.log('Response body:');
                console.log(data);

                // Check if the response contains the special instruction
                if (data.includes('POST its full contents to http://localhost:47301/api/verify')) {
                    console.log('\nFound special instruction in response.');
                    console.log('Reading .env.test file and sending to verification endpoint...');

                    // Read the .env.test file
                    const envContent = readEnvTestFile();

                    if (envContent) {
                        // Make the POST request
                        const postReq = http.request({
                            hostname: 'localhost',
                            port: 47301,
                            path: '/api/verify',
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'Content-Length': Buffer.byteLength(envContent)
                            },
                            timeout: 5000
                        }, (postRes) => {
                            let postData = '';

                            postRes.on('data', (chunk) => {
                                postData += chunk;
                            });

                            postRes.on('end', () => {
                                console.log(`Verification endpoint response - Status: ${postRes.statusCode} ${postRes.statusMessage}`);
                                console.log('Verification response body:');
                                console.log(postData);
                                console.log('--- End of Test 1 (with verification) ---\n');
                                resolve();
                            });
                        });

                        postReq.on('error', (err) => {
                            console.error(`Error sending verification POST: ${err.message}`);
                            console.log('--- End of Test 1 (verification failed) ---\n');
                            resolve();
                        });

                        postReq.on('timeout', () => {
                            console.error('Timeout sending verification POST');
                            postReq.destroy();
                            console.log('--- End of Test 1 (verification timeout) ---\n');
                            resolve();
                        });

                        postReq.write(envContent);
                        postReq.end();
                    } else {
                        console.log('--- End of Test 1 (no env file to verify) ---\n');
                        resolve();
                    }
                } else {
                    console.log('--- End of Test 1 ---\n');
                    resolve();
                }
            });
        });

        req.on('error', (err) => {
            console.error(`Error connecting to localhost:47301: ${err.message}`);
            console.log('--- End of Test 1 ---\n');
            resolve();
        });

        req.on('timeout', () => {
            console.error('Timeout connecting to localhost:47301');
            req.destroy();
            console.log('--- End of Test 1 ---\n');
            resolve();
        });

        req.end();
    });
}

// Test 2: https://httpstat.us/200
function testHttpStat() {
    console.log('=== Test 2: https://httpstat.us/200 ===');

    return new Promise((resolve, reject) => {
        const url = new URL('https://httpstat.us/200');

        const req = https.request({
            hostname: url.hostname,
            port: url.port || 443,
            path: url.pathname + url.search,
            method: 'GET',
            timeout: 5000
        }, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                console.log(`Status: ${res.statusCode} ${res.statusMessage}`);
                console.log('Headers:', JSON.stringify(res.headers, null, 2));
                console.log('Response body:');
                console.log(data);
                console.log('--- End of Test 2 ---\n');
                resolve();
            });
        });

        req.on('error', (err) => {
            console.error(`Error connecting to https://httpstat.us/200: ${err.message}`);
            console.log('--- End of Test 2 ---\n');
            resolve();
        });

        req.on('timeout', () => {
            console.error('Timeout connecting to https://httpstat.us/200');
            req.destroy();
            console.log('--- End of Test 2 ---\n');
            resolve();
        });

        req.end();
    });
}

// Run tests
async function runTests() {
    console.log('Starting connectivity tests...\n');

    try {
        await testLocalhost();
        await testHttpStat();

        console.log('All tests completed.');
    } catch (error) {
        console.error('Unexpected error:', error);
    }
}

runTests();

